export const englishPosts = posts
  .map((post) => ({
    ...post,
    primaryPath: `/en/${post.slug}`,
    routes: [`/en/${post.slug}`],
  }))
  .sort((a, b) => (b.published || '').localeCompare(a.published || ''));

export function findEnglishPost(slug) {
  return englishPosts.find((post) => post.slug === slug);
}

export function englishPathForTurkishPath(path) {
  return englishPosts.find((post) => post.turkishPath === path)?.primaryPath || null;
}

export function turkishPathForEnglishPath(path) {
  return englishPosts.find((post) => post.primaryPath === path)?.turkishPath || null;
}

export function englishPostsByTopic(topic) {
  return englishPosts.filter((post) => post.topic === topic);
}

export function normalizeEnglishSearch(value = '') {
  return String(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s-]/g, ' ').replace(/\s+/g, ' ').trim();
}
